use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < keys.len() as int {
        if keys[i as usize] == k {
            return i
        }
        i = i + 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut cap = 0
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0].clone()
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let idx = find(keys.clone(), k)
            if idx >= 0 {
                keys.remove(idx as usize)
                vals.remove(idx as usize)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() as int > cap {
                let last = keys.len() - 1
                println("evict {}", keys[last])
                keys.remove(last)
                vals.remove(last)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let idx = find(keys.clone(), k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx as usize]
                keys.remove(idx as usize)
                vals.remove(idx as usize)
                keys.insert(0, k)
                vals.insert(0, v)
                println("{}", v)
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        s = s + " "
                    }
                    s = s + keys[i].to_string()
                    i = i + 1
                }
                println("{}", s)
            }
        }
    }
}

